export function catalogCoordinates(
  slug: string,
  fallback?: { latitude?: number; longitude?: number }
): { latitude: number; longitude: number } | null {
  const hit = TRICITY_PROJECT_COORDINATES[slug];
  if (hit) return { latitude: hit.lat, longitude: hit.lng };
  if (fallback?.latitude != null && fallback?.longitude != null) {
    return { latitude: fallback.latitude, longitude: fallback.longitude };
  }
  return null;
}
